
/* ===== 주인공 스킨 ===== 스프라이트 시트(1024×1536, 6칸)는 크기 조절 없이 원본 그대로 쓰고, 칸만 잘라서 보여줘요.
   칸 순서: 0 정면 · 1 뒤 · 2 옆(왼쪽) · 3 정면 걷기 · 4 뒤 걷기 · 5 옆 걷기 */
(function(){
 const FX=388,FS=256;
 const SHEET={scarf:'data:image/png;base64,',hood:'data:image/png;base64,',girl:'data:image/png;base64,'};
 const SKINS=[
  {id:'base',name:'기본 주인공',tag:'처음부터 함께한 모습',story:'처음 모험을 떠나던 날 그대로의 트레이너예요. 가방에는 아직 포켓몬 카드 몇 장과 연필 한 자루뿐이지만, 문제를 하나 풀 때마다 파트너와 함께 조금씩 강해져요.'},
  {id:'scarf',name:'붉은 목도리 소년',tag:'바람에 날리는 붉은 목도리',story:'할아버지가 둘러 준 붉은 목도리가 소년의 부적이에요. 길을 잃고 울던 날, 목도리가 바람에 펄럭이며 집으로 가는 길을 알려 주었대요. 그 뒤로 소년은 어려운 문제 앞에서도 목도리를 고쳐 매고 말해요. “틀려도 괜찮아, 다시 풀면 되니까!”',cls:'pskSheetA',sheet:SHEET.scarf,cost:2,g:'m',nf:1},
  {id:'hood',name:'보랏빛 후드 마법사',tag:'어둠 속에서 빛나는 눈빛',story:'아무도 얼굴을 본 적 없는 후드 마법사예요. 어둠 속에서 푸른 눈빛만 반짝이지만, 사실은 틀린 문제를 모아 둔 오답 노트를 가장 아끼는 다정한 마법사랍니다. 어려운 수식도 별빛 주문으로 척척 풀어내요.',cls:'pskSheetB',sheet:SHEET.hood,cost:2},
  {id:'girl',name:'별 리본 소녀',tag:'별 리본이 반짝이는 보랏빛 곱슬머리',story:'별이 가장 잘 보이는 언덕에서 매일 밤 별자리 수수께끼를 풀던 소녀예요. 어느 날 머리의 큰 리본 속 별이 반짝이며 ‘문제를 푸는 모험’을 알려 주었대요. 그 뒤로 리본의 별은 정답을 맞힐 때마다 조금씩 더 밝아져요.',cls:'pskSheetC',sheet:SHEET.girl,cost:2,g:'f',nf:1}
 ];
 try{const st=document.createElement('style');st.id='psk-sheets';st.textContent=SKINS.filter(s=>s.cls).map(s=>`.${s.cls}{background-image:url(${s.sheet})}`).join('\n');document.head.appendChild(st);}catch(e){}
 const byId=id=>SKINS.find(s=>s.id===id)||SKINS[0];
 const isMale=()=>{try{return !(S.meta&&S.meta.pg==='f');}catch(e){return true;}};
 /* 스킨의 g: 'm'(남자 주인공 전용) · 'f'(여자 주인공 전용) · 없으면 둘 다 입을 수 있어요 */
 const fits=sk=>!sk.g||sk.g===(isMale()?'m':'f');
 /* ===== 스킨 재화: 단원·영역을 마스터(별 5개 모두)할 때마다 1개 · 재화로 스킨을 사요 =====
   마스터 기준 · 수학: 그 단원의 개념이 모두 별 5개 / 국어: 유형 하나가 별 5개 / 영어: 레벨별 유형 하나가 별 5개
   재화 = (마스터한 곳 수) − (쓴 재화). 한 번 받은 곳은 m.pskMs에 기록해서 다시 받지 않아요. 보유 스킨은 m.pskOwn, 쓴 재화는 m.pskSp. */
 const costOf=sk=>Math.max(0,Math.floor(+sk.cost||0));
 function pm(){const m=S.meta;if(!m||typeof m!=='object')return null;
  if(!m.pskOwn||typeof m.pskOwn!=='object'){m.pskOwn={};const w=m.psk;if(w&&w!=='base'&&SKINS.some(s=>s.id===w))m.pskOwn[w]=1;} /* 예전에 무료로 입던 스킨은 그대로 내 것으로 남겨요 */
  if(!m.pskMs||typeof m.pskMs!=='object')m.pskMs={};
  if(typeof m.pskSp!=='number'||!(m.pskSp>=0))m.pskSp=0;
  return m;}
 const owned=id=>{if(id==='base')return true;const m=pm();return !!(m&&m.pskOwn[id]);};
 const bal=()=>{const m=pm();return m?Math.max(0,Object.keys(m.pskMs).length-m.pskSp):0;};
 function mastered(){const m=S.meta,out=[];if(!m)return out;
  try{if(typeof mathMastered==='function')mathMastered().forEach(k=>out.push('m:'+k));}catch(e){}
  try{const T=(typeof EN_TYPE_NAME!=='undefined')?EN_TYPE_NAME:null;for(const id in (m.enSk||{})){const e=m.enSk[id],t=String(id).split(':')[2];if(e&&e.st>=5&&T&&T[t])out.push('e:'+id);}}catch(e){}
  try{const T=(typeof KO_TYPE!=='undefined')?KO_TYPE:null;for(const id in (m.xSk||{})){const e=m.xSk[id];if(e&&e.k==='ko'&&e.st>=5&&T&&T[e.t])out.push('k:'+id);}}catch(e){}
  return out;}
 function sync(){try{const m=pm();if(!m||!m.gs)return 0;let n=0;const first=!m.pskInit;
  mastered().forEach(k=>{if(!m.pskMs[k]){m.pskMs[k]=(typeof today==='function'?today():1);n++;}});
  m.pskInit=true;
  if(n>0){try{autoSave();}catch(e){}
   try{toast(first&&n>1?`🎁 지금까지 마스터한 ${n}곳이 스킨 재화 ${n}개가 됐어요!`:`🏅 마스터! 스킨 재화 +${n}`);}catch(e){}
   try{sfx('ok');}catch(e){}}
  return n;}catch(e){return 0;}}
 {const ocb=window.checkBadges;if(typeof ocb==='function')window.checkBadges=function(){const r=ocb.apply(this,arguments);try{sync();}catch(e){}return r;};}
 setInterval(()=>{try{if(!document.hidden)sync();}catch(e){}},3000);
 window.pskSync=sync;window.pskBal=bal;
 const curId=()=>{try{const sk=byId(S.meta&&S.meta.psk);return owned(sk.id)&&fits(sk)?sk.id:'base';}catch(e){return 'base';}};
 const sp=(sk,f,s)=>`<span class="pskSp ${sk.cls}" style="--s:${s};--f:${f}"></span>`;
 const baseImg=()=>{try{return isMale()?CHAR_ART.hero_m:CHAR_ART.hero_f;}catch(e){return '';}};
 /* 기본 주인공 앞모습 gif (남/여) · 못 불러오면 예전 일러스트로 돌아가요 */
 const BASE_GIF={m:'boy_front.gif',f:'girl_front.gif'};
 const gifUrls=()=>{const f=BASE_GIF[isMale()?'m':'f'];return ['https://raw.githubusercontent.com/regecha/pokemath/main/'+f,'https://cdn.jsdelivr.net/gh/regecha/pokemath@main/'+f];};
 window.pskBaseGifErr=function(im){try{const u=gifUrls(),i=+im.dataset.gi||0;if(i+1<u.length){im.dataset.gi=i+1;im.src=u[i+1];}else{im.onerror=null;im.src=baseImg();}}catch(e){}};

 /* 이야기 속 주인공 얼굴: 고른 스킨의 정면 모습을 그대로 오려서 써요 (남자 주인공만) */
 const PORT={},FR={},IM={},OV=new WeakMap();
 function mkPort(sk){
  const im=new Image();
  im.onload=()=>{try{
   const c=document.createElement('canvas');c.width=FS;c.height=FS;const x=c.getContext('2d');
   x.drawImage(im,FX,0,FS,FS,0,0,FS,FS);
   const d=x.getImageData(0,0,FS,FS).data;let x0=FS,y0=FS,x1=-1,y1=-1;
   for(let y=0;y<FS;y++)for(let xx=0;xx<FS;xx++){if(d[(y*FS+xx)*4+3]>40){if(xx<x0)x0=xx;if(xx>x1)x1=xx;if(y<y0)y0=y;if(y>y1)y1=y;}}
   if(x1<0)return;x0=Math.max(0,x0-2);y0=Math.max(0,y0-2);x1=Math.min(FS-1,x1+2);y1=Math.min(FS-1,y1+2);
   const w=x1-x0+1,h=y1-y0+1,c2=document.createElement('canvas');c2.width=w;c2.height=h;
   c2.getContext('2d').drawImage(c,x0,y0,w,h,0,0,w,h);
   PORT[sk.id]=c2.toDataURL('image/png');
  }catch(e){}
  /* 체육관·필드: 칸(256×256)을 크기 조절 없이 그대로 정사각 캔버스 아래쪽에 얹어요 (흔들림용 좌우 뒤집기 포함) */
  try{
   const SQ=272,rows={down:[0,3],up:[1,4],left:[2,5]},fr={};
   for(const d in rows)for(let w=0;w<2;w++)for(let fl=0;fl<2;fl++){
    const c=document.createElement('canvas');c.width=SQ;c.height=SQ;const x=c.getContext('2d');x.imageSmoothingEnabled=false;
    if(fl){x.translate(SQ,0);x.scale(-1,1);}
    x.drawImage(im,FX,rows[d][w]*FS,FS,FS,(SQ-FS)/2,SQ-FS,FS,FS);
    fr[d+w+fl]=c.toDataURL('image/png');
   }
   FR[sk.id]=fr;
  }catch(e){}
  IM[sk.id]=im;};
  im.src=sk.sheet;
 }
 SKINS.filter(s=>s.sheet).forEach(mkPort);

 /* ===== 닌자 어드벤처 캐릭터 스킨 (pixel-boy · CC0) =====
    캐릭터 목록은 GitHub(pixel-boy/NinjaAdventure)의 Characters/이름/SpriteSheet.png 를 자동으로 찾아서 만들어요.
    원본은 16×16 도트(4방향×여러 줄)라서, 불러올 때 16배로 키워 이 게임의 스킨 시트(1024×1536, 6칸) 모양으로 바꿔요. */
 const NJ_COST=2; /* 닌자 스킨 하나의 가격(💎) — 여기 숫자만 바꾸면 돼요 */
 const NJ_KO={Ninja:'닌자',Boy:'소년',Girl:'소녀',Woman:'여인',Man:'남자',Villager:'마을 사람',Monk:'스님',Master:'사부',Knight:'기사',Samurai:'사무라이',Princess:'공주',Prince:'왕자',King:'왕',Queen:'여왕',Noble:'귀족',Old:'늙은',Skeleton:'해골',Hunter:'사냥꾼',Child:'아이',Inspector:'조사관',Masked:'복면',Frog:'개구리',Blue:'파랑',Red:'빨강',Green:'초록',Gray:'회색',Grey:'회색',Dark:'어둠',White:'하양',Black:'검정',Yellow:'노랑',Purple:'보라',Pink:'분홍',Orange:'주황',Brown:'갈색',Gold:'황금',Cat:'고양이',Dog:'강아지',Fox:'여우',Panda:'판다',Tiger:'호랑이',Bear:'곰',Priest:'사제',Mage:'마법사',Wizard:'마법사',Guard:'경비병',Soldier:'병사',Merchant:'상인',Farmer:'농부',Fisher:'낚시꾼',Fisherman:'어부',Chef:'요리사',Doctor:'의사',Thief:'도둑',Assassin:'암살자',Warrior:'전사',Archer:'궁수',Demon:'악마',Spirit:'정령',Ghost:'유령',Robot:'로봇',Cyclop:'외눈 거인',Eskimo:'에스키모',Tribal:'부족',Sensei:'스승',Shogun:'쇼군',Geisha:'게이샤',Oni:'도깨비',Tengu:'텐구',Kitsune:'여우 요괴',Lion:'사자',Reaper:'저승사자',Mother:'어머니',Father:'아버지',Grandma:'할머니',Grandpa:'할아버지',Lord:'영주',Lady:'귀부인',Hermit:'은둔자',Statue:'석상'};
 const njName=k=>{const t=k.replace(/_/g,' ').replace(/([a-z])([A-Z])/g,'$1 $2').replace(/([A-Za-z])(\d)/g,'$1 $2').split(/\s+/);return t.map(w=>NJ_KO[w]||w).join(' ');};
 const njRx=/(?:^|\/)Characters\/([^\/]+)\/SpriteSheet\.png$/i;
 const njPick=paths=>{const o={};paths.forEach(p=>{if(njRx.test(p)&&!/\/(Monsters|Monster|Boss|Animals|Animal|Enemy|Enemies)\//i.test(p)){o[njRx.exec(p)[1]]=p.replace(/^\//,'');}});return Object.keys(o).sort().map(k=>({key:k,path:o[k]}));};
 async function njList(){
  try{const r=await fetch('https://api.github.com/repos/pixel-boy/NinjaAdventure/git/trees/main?recursive=1');if(r.ok){const j=await r.json();const l=njPick((j.tree||[]).filter(t=>t.type==='blob').map(t=>t.path));if(l.length)return l;}}catch(e){}
  try{const r=await fetch('https://data.jsdelivr.com/v1/packages/gh/pixel-boy/NinjaAdventure@main?structure=flat');if(r.ok){const j=await r.json();const l=njPick((j.files||[]).map(f=>f.name));if(l.length)return l;}}catch(e){}
  return [];}
 function njReg(list){list.forEach(c=>{const id='nj_'+c.key.toLowerCase().replace(/[^a-z0-9]/g,'');if(SKINS.some(s=>s.id===id))return;
  SKINS.push({id,name:njName(c.key),tag:'닌자 어드벤처 · '+c.key,cost:NJ_COST,nj:1,path:c.path});});}
 try{const c=JSON.parse(localStorage.getItem('njChars1')||'null');if(c&&c.length)njReg(c);}catch(e){}
 let njInitP=null;
 function njInit(){if(njInitP)return njInitP;
  njInitP=(async()=>{if(SKINS.some(s=>s.nj))return;const l=await njList();if(l.length){njReg(l);try{localStorage.setItem('njChars1',JSON.stringify(l));}catch(e){}}})().catch(()=>{njInitP=null;});
  return njInitP;}
 const njSrc={};
 function njLoad(sk){if(njSrc[sk.id])return njSrc[sk.id];
  const p=encodeURI(sk.path),urls=['https://raw.githubusercontent.com/pixel-boy/NinjaAdventure/main/'+p,'https://cdn.jsdelivr.net/gh/pixel-boy/NinjaAdventure@main/'+p];
  njSrc[sk.id]=new Promise((res,rej)=>{let i=0;const next=()=>{if(i>=urls.length){delete njSrc[sk.id];rej(new Error('load'));return;}const im=new Image();im.crossOrigin='anonymous';im.onload=()=>res(im);im.onerror=next;im.src=urls[i++];};next();});
  return njSrc[sk.id];}
 /* 작은 미리보기(목록용) */
 function njThumb(sk,im){try{const cw=im.width/4,c=document.createElement('canvas');c.width=c.height=128;const x=c.getContext('2d');x.imageSmoothingEnabled=false;x.drawImage(im,0,0,cw,cw,0,0,128,128);sk.thumb=c.toDataURL('image/png');}catch(e){}}
 const njStyle=(()=>{const st=document.createElement('style');st.id='psk-nj';document.head.appendChild(st);return st;})();
 /* 스킨 시트 만들기: 칸 순서 0 정면 · 1 뒤 · 2 옆(왼쪽) · 3 정면 걷기 · 4 뒤 걷기 · 5 옆 걷기 (원본 열: 아래·위·왼쪽·오른쪽) */
 async function ensureSheet(sk){
  if(!sk||!sk.nj||sk.cls)return sk;
  const im=await njLoad(sk);njThumb(sk,im);
  const cw=im.width/4,cv=document.createElement('canvas');cv.width=1024;cv.height=1536;const x=cv.getContext('2d');x.imageSmoothingEnabled=false;
  [[0,0],[1,0],[2,0],[0,1],[1,1],[2,1]].forEach(([c,r],i)=>x.drawImage(im,c*cw,r*cw,cw,cw,FX,i*FS,FS,FS));
  sk.sheet=cv.toDataURL('image/png');sk.cls='pskNj_'+sk.id;
  njStyle.textContent+=`.${sk.cls}{background-image:url(${sk.sheet})}\n`;
  mkPort(sk);
  return sk;}
 function njThumbs(){return njInit().then(()=>Promise.all(SKINS.filter(s=>s.nj&&!s.thumb).map(s=>njLoad(s).then(im=>njThumb(s,im)).catch(()=>{}))));}
 /* 입고 있는 닌자 스킨은 게임 시작 때 미리 준비해요 */
 njInit();
 setInterval(()=>{try{const id=S.meta&&S.meta.psk,sk=id&&SKINS.find(s=>s.id===id);if(sk&&sk.nj&&!sk.cls&&owned(id))ensureSheet(sk).catch(()=>{});}catch(e){}},2000);
 const oldHero=window.charHero;
 window.charHero=function(){try{{const p=PORT[curId()];if(p)return p;}}catch(e){}return typeof oldHero==='function'?oldHero():baseImg();};

 /* 체육관 · 성 · 챔피언 필드(gp)의 주인공 그림: 스킨을 입었으면 스킨 칸을 써요 (남자 주인공만) */
 const oldGHS=window.gpHeroSpr;
 if(typeof oldGHS==='function')window.gpHeroSpr=function(dir,walk,flip){
  try{{const f=FR[curId()];if(f){const d=dir==='right'?'left':dir,u=f[d+(walk?1:0)+((flip&&!((d==='down'||d==='up')&&(byId(curId()).nf)))?1:0)];if(u)return u;}}}catch(e){}
  return oldGHS.apply(this,arguments);};

 /* 16×16 도트 판(끝없는 모험 필드 · 풀숲 연출)에서는 같은 자리·같은 키로, 원본 해상도 그대로 위에 얹어 그려요 */
 setInterval(()=>{const now=performance.now();document.querySelectorAll('canvas.pskOv').forEach(o=>{const c=o._cv;if(!c||!c.isConnected){o.remove();return;}o.style.display=(now-o._t>400)?'none':'';});},250);
 window.pskId=()=>{try{return curId()!=='base'?curId():'';}catch(e){return '';}};
 /* 풀이 다리를 덮는 그림: 메인 캔버스에 그린 뒤, 스킨 그림(위에 얹은 캔버스)에도 같은 풀을 한 번 더 그려요 */
 window.pskGD=function(g,img){
  const a=Array.prototype.slice.call(arguments,1);
  g.drawImage.apply(g,a);
  try{
   const om=OV.get(g.canvas),ov=om&&om.me;if(!ov||!ov.isConnected||performance.now()-ov._t>120)return;
   const t=g.getTransform?g.getTransform():{a:1,d:1,e:0,f:0},k=ov.width/g.canvas.width,o=ov.getContext('2d');
   o.save();o.imageSmoothingEnabled=false;
   o.drawImage(a[0],a[1],a[2],a[3],a[4],(a[5]*t.a+t.e)*k,(a[6]*t.d+t.f)*k,a[7]*t.a*k,a[8]*t.d*k);
   o.restore();
  }catch(e){}};
 window.pskDraw=function(g,dir,walk,x,y,flip,size,sid,key){
  try{
   const im=sid?IM[sid]:IM[curId()];if(!im||!im.complete||!im.naturalWidth)return false;const nf=(()=>{try{const k=SKINS.find(z=>z.id===(sid||curId()));return !!(k&&k.nf);}catch(e){return false;}})();
   const cv=g.canvas,row=[[0,3],[1,4],[2,5],[2,5]][dir];if(!cv||!cv.isConnected||!row||!cv.parentNode)return false;
   const cw=cv.clientWidth,ch=cv.clientHeight;if(!cw||!ch)return false;
   let om=OV.get(cv);if(!om){om={};OV.set(cv,om);}const kk=key||'me';let ov=om[kk];
   if(!ov||!ov.isConnected){ov=document.createElement('canvas');ov.className='pskOv';ov._cv=cv;ov.style.cssText='position:absolute;pointer-events:none;image-rendering:auto';cv.parentNode.insertBefore(ov,cv.nextSibling);om[kk]=ov;}
   const dpr=Math.min(window.devicePixelRatio||1,3),W=Math.round(cw*dpr),H=Math.round(ch*dpr);
   if(ov.width!==W||ov.height!==H){ov.width=W;ov.height=H;}
   ov.style.left=cv.offsetLeft+'px';ov.style.top=cv.offsetTop+'px';ov.style.width=cw+'px';ov.style.height=ch+'px';
   const t=g.getTransform?g.getTransform():{a:1,d:1,e:0,f:0},k=W/cv.width;
   const sz=(size||16)*t.a*k,dh=sz,dw=dh*230/248,dx=(x*t.a+t.e)*k+(sz-dw)/2,dy=(y*t.d+t.f)*k;
   const o=ov.getContext('2d');o.clearRect(0,0,W,H);o.imageSmoothingEnabled=true;o.imageSmoothingQuality='high';
   o.save();if(dir===3||(flip&&!(dir<2&&nf))){o.translate(dx+dw,0);o.scale(-1,1);o.drawImage(im,400,row[walk?1:0]*FS+4,230,248,0,dy,dw,dh);}
   else o.drawImage(im,400,row[walk?1:0]*FS+4,230,248,dx,dy,dw,dh);
   o.restore();ov._t=performance.now();ov.style.display='';return true;
  }catch(e){return false;}};

 /* 홈 화면 조각 */
 window.pskBtn=()=>SKINS.some(fits)?`<button class="btn ghost sm" id=hPskin>${(typeof I==='function'&&I('star'))||'✨'} 스킨<span class=mbLong> 변경</span>${(()=>{try{const b=bal();return b>0?` <span style="color:#d97a00">💎${b}</span>`:'';}catch(e){return '';}})()}</button>`:'';
 window.pskHub=()=>{const sk=byId(curId());
  if(sk&&sk.cls)return `<span class=htSkinAv>${sp(sk,0,.19)}</span>`;
  const u=gifUrls();return `<span class=htSkinAv><img class=htSkinGif src="${u[0]}" data-gi=0 onerror="(function(i){var g=${JSON.stringify(u).replace(/"/g,'&quot;')},n=(+i.dataset.gi||0)+1;if(n<g.length){i.dataset.gi=n;i.src=g[n];}else{i.onerror=null;i.parentNode.style.display='none';}})(this)" alt=""></span>`;};

 /* 시작 타이틀 화면용: 스킨 뒷모습(칸 1)을 여백 없이 잘라서 돌려줘요. 아직 그림이 안 불러와졌으면 null(기본 주인공) → 불러온 뒤 타이틀이면 한 번 다시 그려요 */
 const TA={};
 window.pskTitleWorn=()=>{try{const sk=byId(curId());return !!(sk&&sk.cls);}catch(e){return false;}};
 window.pskTitleArt=()=>{try{
  const sk=byId(curId());if(!sk||!sk.cls)return null;if(TA[sk.id])return TA[sk.id];
  const im=IM[sk.id];if(!im){if((TA._r=(TA._r||0)+1)<=20)setTimeout(()=>{try{if(S.screen==='title')renderTitle();}catch(e){}},300);return null;}
  if(!im.complete||!im.naturalWidth){if(!im._tw){im._tw=1;im.addEventListener('load',()=>{try{if(S.screen==='title')renderTitle();}catch(e){}});}return null;}
  const c=document.createElement('canvas');c.width=FS;c.height=FS;const x=c.getContext('2d');x.drawImage(im,FX,FS,FS,FS,0,0,FS,FS);
  const d=x.getImageData(0,0,FS,FS).data;let x0=FS,y0=FS,x1=-1,y1=-1;
  for(let yy=0;yy<FS;yy++)for(let xx=0;xx<FS;xx++)if(d[(yy*FS+xx)*4+3]>20){if(xx<x0)x0=xx;if(xx>x1)x1=xx;if(yy<y0)y0=yy;if(yy>y1)y1=yy;}
  if(x1<0)return null;const w=x1-x0+1,h=y1-y0+1,o=document.createElement('canvas');o.width=w;o.height=h;o.getContext('2d').drawImage(c,x0,y0,w,h,0,0,w,h);
  return TA[sk.id]={url:o.toDataURL('image/png'),w:106*w/h};
 }catch(e){return null;}};

 /* 팝업 */
 const SEG=[
  {t:'정면으로 서 있어요',d:1300,f:[0],a:[0,-14],b:[0,-14]},
  {t:'앞으로 걸어요',d:1500,f:[3,0],a:[0,-14],b:[0,14]},
  {t:'왼쪽으로 걸어요',d:1500,f:[5,2],a:[0,14],b:[-34,14]},
  {t:'뒤로 걸어요',d:1500,f:[4,1],a:[-34,14],b:[-34,-14]},
  {t:'오른쪽으로 걸어요',d:1500,f:[5,2],flip:1,a:[-34,-14],b:[0,-14]},
  {t:'정면을 봐요',d:1300,f:[0],a:[0,-14],b:[0,-14]}
 ];
 const TOTAL=SEG.reduce((n,g)=>n+g.d,0);
 let timer=0,sel='base',changed=false,armed=0,armT=0;
 const stop=()=>{clearInterval(timer);timer=0;};
 const scale=()=>{try{const v=document.getElementById('pskView');if(v&&v.clientWidth&&v.clientHeight)return Math.max(.4,Math.min(1,v.clientHeight/300,v.clientWidth/256));return window.matchMedia('(max-width:640px)').matches?.6:1;}catch(e){return 1;}};

 function paintStage(){
  stop();
  const sk=byId(sel),view=document.getElementById('pskView');if(!view)return;
  if(sk.nj&&!sk.cls){view.innerHTML='<div style="color:#ffe27a;padding:24px;text-align:center">불러오는 중...</div>';document.getElementById('pskNm').textContent=sk.name;document.getElementById('pskDir').textContent='';document.getElementById('pskTg').textContent=sk.tag;
   ensureSheet(sk).then(()=>{if(sel===sk.id&&document.getElementById('pskView'))paintStage();}).catch(()=>{const v=document.getElementById('pskView');if(v&&sel===sk.id)v.innerHTML='<div style="color:#ffb0b0;padding:24px;text-align:center">그림을 불러오지 못했어요.<br>인터넷을 확인해 주세요</div>';});
   return;}
  const s=scale(),size=Math.round(FS*s);
  view.innerHTML=`<div class=pskMv id=pskMv style="width:${size}px;height:${size}px">${sk.cls?`<span class="pskSp ${sk.cls}" id=pskAct style="--s:${s};--f:0"></span>`:`<img class=pskBaseImg id=pskAct src="${gifUrls()[0]}" data-gi=0 onerror="pskBaseGifErr(this)" alt="">`}</div>`;
  document.getElementById('pskNm').textContent=sk.name;
  {const st=document.getElementById('pskSt');if(st)st.textContent=sk.story||'';}
  document.getElementById('pskTg').textContent=(sk.cls?sk.tag:'걷는 도트 모습은 없어요 · '+sk.tag)+(owned(sk.id)?'':' · 💎 재화 '+costOf(sk)+'개로 살 수 있어요');
  const mv=document.getElementById('pskMv'),act=document.getElementById('pskAct'),dir=document.getElementById('pskDir');
  const t0=performance.now();let lastSeg=-1;
  const tick=()=>{
   if(!mv.isConnected){stop();return;}
   const t=(performance.now()-t0)%TOTAL;let acc=0,i=0;
   for(;i<SEG.length;i++){if(t<acc+SEG[i].d)break;acc+=SEG[i].d;}
   i=Math.min(i,SEG.length-1);const g=SEG[i],p=(t-acc)/g.d;
   const x=(g.a[0]+(g.b[0]-g.a[0])*p)*s,y=(g.a[1]+(g.b[1]-g.a[1])*p)*s;
   if(i!==lastSeg){lastSeg=i;dir.textContent=sk.cls?g.t:'기본 모습이에요';}
   if(!sk.cls){mv.style.transform=`translate(-50%,-50%) translateY(${Math.sin(t/260)*3}px)`;return;}
   const step=Math.floor((t-acc)/170),walking=g.f.length>1;
   act.style.setProperty('--f',g.f[walking?step%g.f.length:0]);
   act.style.transform=g.flip?'scaleX(-1)':'';
   mv.style.transform=`translate(-50%,-50%) translate(${x}px,${y+(walking&&step%2?-2*s:0)}px)`;
  };
  tick();timer=setInterval(tick,50);
 }
 function paintList(){
  const list=document.getElementById('pskList');if(!list)return;const me=curId();
  list.innerHTML=SKINS.filter(fits).map(sk=>`<button type=button class="pskCard${sk.id===sel?' on':''}${sk.id===me?' wear':''}${owned(sk.id)?'':' lock'}" data-id="${sk.id}"><span class=pskTh>${sk.nj&&sk.thumb?`<img src="${sk.thumb}" alt="" style="object-fit:contain">`:(sk.cls?sp(sk,0,.42):(sk.nj?'':`<img src="${baseImg()}" alt="">`))}</span><b class=jua>${sk.name}</b>${sk.id===me?'<i class=pskBadge>착용 중</i>':(owned(sk.id)?'':`<i class=pskLock>🔒 💎${costOf(sk)}</i>`)}</button>`).join('');
  list.querySelectorAll('.pskCard').forEach(b=>b.onclick=()=>{try{sfx('tap');}catch(e){}if(sel===b.dataset.id)return;sel=b.dataset.id;armed=0;clearTimeout(armT);paintList();paintStage();paintBtn();});
 }
 function paintBtn(){const b=document.getElementById('pskWear');if(!b)return;const sk=byId(sel),own=owned(sel),on=sel===curId(),c=costOf(sk),have=bal(),can=have>=c;
  b.textContent=own?(on?'착용 중이에요':'이 스킨 입기'):(!can?`재화가 모자라요 (💎 ${c}개 필요 · 지금 ${have}개)`:armed?`한 번 더 누르면 사요! (💎 ${c}개)`:`💎 ${c}개로 구매하기`);
  b.classList.toggle('ghost',own?on:!can);b.classList.toggle('red',own?!on:can);}
 function paintWal(){const w=document.getElementById('pskWal');if(!w)return;const m=pm(),got=m?Object.keys(m.pskMs).length:0;
  w.innerHTML=`💎 스킨 재화 <b>${bal()}</b>개 <span class=mut style="font-size:12px">(지금까지 ${got}개 얻음)</span><div class=pskHow>단원·영역의 별을 5개까지 모두 모으면(🏅 마스터) 재화 1개!<br>수학 단원 · 국어 영역 · 영어 영역이 해당돼요</div>`;}
 function close(){stop();clearTimeout(armT);armed=0;closeM();if(changed){changed=false;try{if(S.screen==='hub')renderHub();}catch(e){}}}
 window.pskOpen=function(){
  try{sync();}catch(e){}sel=curId();changed=false;armed=0;clearTimeout(armT);
  M(`<div class=pskPop><h2 class=jua>스킨 변경</h2>
    <div class=pskWal id=pskWal></div>
   <div class=pskBody>
    <div class=pskStage><div class=pskView id=pskView></div><div class="pskDir jua" id=pskDir></div></div>
    <div class=pskStory><div class="pskNm jua" id=pskNm></div><div class="pskTg mut" id=pskTg></div><p class=pskSt id=pskSt></p></div>
    <div class=pskList id=pskList></div>
   </div>
   <div class=row style="margin-top:12px"><button class="btn red" data-a=wear id=pskWear></button><button class="btn ghost" data-a=x>닫기</button></div></div>`,
  {wear:()=>{
    if(owned(sel)){if(sel===curId())return;S.meta.psk=sel;changed=true;try{autoSave();}catch(e){}try{sfx('ok');}catch(e){}try{toast(`${byId(sel).name} 스킨을 입었어요!`);}catch(e){}paintList();paintBtn();return;}
    const sk=byId(sel),c=costOf(sk),m=pm();
    if(!m||bal()<c){try{sfx('tap');}catch(e){}try{toast(`스킨 재화가 ${c-bal()}개 모자라요. 단원·영역을 마스터해 보세요!`);}catch(e){}return;}
    if(!armed){armed=1;clearTimeout(armT);armT=setTimeout(()=>{armed=0;paintBtn();},4000);try{sfx('tap');}catch(e){}paintBtn();return;} /* 실수로 사지 않게 한 번 더 눌러야 사져요 */
    armed=0;clearTimeout(armT);m.pskSp+=c;m.pskOwn[sel]=1;m.psk=sel;changed=true;try{autoSave();}catch(e){}try{sfx('ok');}catch(e){}try{toast(`${sk.name} 스킨을 샀어요! 바로 입었어요 ✨`);}catch(e){}
    paintWal();paintList();paintStage();paintBtn();},
   x:close,_close:close},{wide:true});
  paintWal();paintList();paintStage();paintBtn();
  try{njThumbs().then(()=>{if(document.getElementById('pskList')){paintList();paintBtn();}});}catch(e){}
 };
})();
